/*
    Refait les tables Unicode du tokenizer (engine/hf_unicode.h) : les classes de caractères des
    pré-découpages (\p{L…}, \p{M}, \p{N}, \p{P}, \p{S}, \p{Z}), les classes de combinaison canoniques
    et les paires de la composition canonique.  Remplace tools/make_unicode_table.py (de l'original,
    qui lisait le module unicodedata de Python) depuis Gulliver 7.17.1 (décision de l'humain du
    28 novembre 2026 : tout en C++).

    Les données viennent de l'ICU de macOS (libicucore) : catégorie, classe de combinaison et âge de
    chaque caractère (uchar.h), décomposition d'un seul niveau et composition de deux caractères
    (unorm2).  Une version d'Unicode donnée (--unicode 15.1, la version de la table actuelle) écarte les
    caractères apparus après elle ; les propriétés qu'Unicode a changées depuis restent celles du
    système (U+0295, lettre minuscule en 15.1, autre lettre depuis : seul écart avec la table de 15.1).
    Seules les tables et la ligne « Generated by » changent ; le reste du fichier, écrit à la
    main, est gardé tel quel.

        build/macos-gulliver/tools/make_unicode_table --unicode 15.1 engine/hf_unicode.h > nouveau.h
*/

#include <algorithm>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

#include <unicode/uchar.h>
#include <unicode/utf16.h>

// Le module de normalisation d'ICU (unicode/unorm2.h de l'interface C stable), que libicucore exporte mais dont le
// SDK de macOS ne livre pas l'en-tête.
extern "C"
{
    typedef struct UNormalizer2 UNormalizer2;
    const UNormalizer2* unorm2_getNFCInstance(UErrorCode* status);
    int32_t unorm2_getRawDecomposition(const UNormalizer2* norm2, UChar32 c, UChar* decomposition, int32_t capacity,
        UErrorCode* status);
    UChar32 unorm2_composePair(const UNormalizer2* norm2, UChar32 a, UChar32 b);
}

namespace
{
    int version_major = 0, version_minor = 0;   // 0.0 : tous les caractères que connaît le système

    // Vrai quand cp existe dans la version d'Unicode retenue.
    bool in_version(uint32_t cp)
    {
        UVersionInfo age;
        u_charAge(static_cast<UChar32>(cp), age);
        if (age[0] == 0 && age[1] == 0) return false;   // jamais assigné
        if (version_major == 0) return true;
        return age[0] < version_major || (age[0] == version_major && age[1] <= version_minor);
    }

    // La classe des pré-découpages (l'énumération char_class de hf_unicode.h).
    unsigned char_class(uint32_t cp)
    {
        if (!in_version(cp)) return 0;
        // La zone à usage privé est « other » pour Unicode ; l'ICU d'Apple y range ses propres symboles en So.
        if ((cp >= 0xE000 && cp < 0xF900) || cp >= 0xF0000) return 0;
        switch (u_charType(static_cast<UChar32>(cp)))
        {
        case U_UPPERCASE_LETTER: return 1;
        case U_LOWERCASE_LETTER: return 2;
        case U_TITLECASE_LETTER: return 3;
        case U_MODIFIER_LETTER: return 4;
        case U_OTHER_LETTER: return 5;
        case U_NON_SPACING_MARK: case U_COMBINING_SPACING_MARK: case U_ENCLOSING_MARK: return 6;
        case U_DECIMAL_DIGIT_NUMBER: case U_LETTER_NUMBER: case U_OTHER_NUMBER: return 7;
        case U_CONNECTOR_PUNCTUATION: case U_DASH_PUNCTUATION: case U_START_PUNCTUATION: case U_END_PUNCTUATION:
        case U_INITIAL_PUNCTUATION: case U_FINAL_PUNCTUATION: case U_OTHER_PUNCTUATION: return 8;
        case U_MATH_SYMBOL: case U_CURRENCY_SYMBOL: case U_MODIFIER_SYMBOL: case U_OTHER_SYMBOL: return 9;
        case U_SPACE_SEPARATOR: case U_LINE_SEPARATOR: case U_PARAGRAPH_SEPARATOR: return 10;
        default: return 0;
        }
    }

    unsigned combining(uint32_t cp)
    {
        return in_version(cp) ? u_getCombiningClass(static_cast<UChar32>(cp)) : 0;
    }

    /*
        Les compositions primaires : cp a une décomposition canonique d'un seul niveau en deux caractères
        a et b, et la composition canonique de a et b redonne cp.  Les deux viennent du module de
        normalisation d'ICU (unorm2), présent dans libicucore mais dont le SDK ne livre pas l'en-tête :
        ses prototypes, de l'interface C stable d'ICU, sont déclarés plus haut.  La normalisation de
        CoreFoundation ne convient pas : elle ne compose pas U+0CCA U+0CD5 en U+0CCB, que demande Unicode.
    */
    std::vector<std::pair<uint64_t, uint32_t>> compositions()
    {
        UErrorCode status = U_ZERO_ERROR;
        const UNormalizer2* nfc = unorm2_getNFCInstance(&status);
        std::vector<std::pair<uint64_t, uint32_t>> pairs;
        if (U_FAILURE(status)) return pairs;
        for (uint32_t cp = 0; cp < 0x110000; ++cp)
        {
            if (!in_version(cp)) continue;
            // Des syllabes hangûl, la table d'origine ne garde que celles de deux lettres (LV) ; celles de trois (LVT)
            // se composent par calcul dans compose(), qui traite d'ailleurs toutes les syllabes avant la table.
            if (cp >= 0xAC00 && cp < 0xD7A4 && (cp - 0xAC00) % 28 != 0) continue;
            UChar raw[32];
            status = U_ZERO_ERROR;
            const int32_t n = unorm2_getRawDecomposition(nfc, static_cast<UChar32>(cp), raw, 32, &status);
            if (n <= 0 || U_FAILURE(status)) continue;
            std::vector<uint32_t> parts;
            for (int32_t i = 0; i < n;)
            {
                UChar32 c;
                U16_NEXT(raw, i, n, c);
                parts.push_back(static_cast<uint32_t>(c));
            }
            if (parts.size() != 2) continue;
            if (static_cast<uint32_t>(unorm2_composePair(nfc, static_cast<UChar32>(parts[0]), static_cast<UChar32>(parts[1])))
                == cp)
                pairs.push_back({(static_cast<uint64_t>(parts[0]) << 21) | parts[1], cp});
        }
        std::sort(pairs.begin(), pairs.end());
        return pairs;
    }

    // Les lignes d'une table : 15 espaces, puis « 0x…, » jusqu'à 100 caractères, comme la table d'origine.
    template <typename T>
    std::string lines_of(const std::vector<T>& values, const char* suffix)
    {
        std::string out, line = "               ";
        char item[40];
        for (const T v : values)
        {
            std::snprintf(item, sizeof(item), " 0x%llx%s,", static_cast<unsigned long long>(v), suffix);
            if (line.size() + std::strlen(item) > 100)
            {
                out += line + "\n";
                line = "               ";
            }
            line += item;
        }
        return out + line + "\n";
    }
}

int main(int argc, char** argv)
{
    std::string path;
    for (int i = 1; i < argc; ++i)
    {
        const std::string a = argv[i];
        if (a == "--unicode" && i + 1 < argc)
        {
            if (std::sscanf(argv[++i], "%d.%d", &version_major, &version_minor) != 2)
            {
                std::fprintf(stderr, "make_unicode_table: --unicode X.Y\n");
                return 2;
            }
        }
        else path = a;
    }
    if (path.empty())
    {
        std::fprintf(stderr, "usage: make_unicode_table [--unicode X.Y] engine/hf_unicode.h > out.h\n");
        return 2;
    }
    std::ifstream f(path);
    if (!f)
    {
        std::fprintf(stderr, "make_unicode_table: cannot read %s\n", path.c_str());
        return 1;
    }
    std::vector<std::string> lines;
    for (std::string l; std::getline(f, l);) lines.push_back(l);

    // Les quatre tables.
    std::vector<uint32_t> classes, combinings;
    unsigned prev = 99;
    for (uint32_t cp = 0; cp < 0x110000; ++cp)
    {
        const unsigned c = char_class(cp);
        if (c != prev) classes.push_back((cp << 4) | c);
        prev = c;
    }
    prev = 999;
    for (uint32_t cp = 0; cp < 0x110000; ++cp)
    {
        const unsigned c = combining(cp);
        if (c != prev) combinings.push_back((cp << 8) | c);
        prev = c;
    }
    const auto pairs = compositions();
    std::vector<uint64_t> keys;
    std::vector<uint32_t> values;
    for (const auto& p : pairs)
    {
        keys.push_back(p.first);
        values.push_back(p.second);
    }
    const std::string tables[4] = {lines_of(classes, ""), lines_of(combinings, ""), lines_of(keys, "ull"),
        lines_of(values, "")};

    // Le fichier, ses tables remplacées dans l'ordre où elles y paraissent.
    char version[32];
    UVersionInfo unicode;
    u_getUnicodeVersion(unicode);
    if (version_major) std::snprintf(version, sizeof(version), "%d.%d.0", version_major, version_minor);
    else std::snprintf(version, sizeof(version), "%d.%d.%d", unicode[0], unicode[1], unicode[2]);
    std::string out;
    int table = 0;
    for (size_t i = 0; i < lines.size(); ++i)
    {
        const std::string& l = lines[i];
        if (l.rfind("// Generated by make_unicode_table", 0) == 0)
        {
            out += std::string("// Generated by make_unicode_table from the Unicode Character Database ") + version + ".\n";
            continue;
        }
        out += l + "\n";
        const bool opens = l.find("static const uint32_t runs[] = {") != std::string::npos
            || l.find("static const uint64_t keys[] = {") != std::string::npos
            || l.find("static const uint32_t values[] = {") != std::string::npos;
        if (opens && table < 4)
        {
            out += tables[table++];
            while (i + 1 < lines.size() && lines[i + 1] != "            };") ++i;
        }
    }
    if (table != 4)
    {
        std::fprintf(stderr, "make_unicode_table: %s has %d tables, not 4\n", path.c_str(), table);
        return 1;
    }
    std::fwrite(out.data(), 1, out.size(), stdout);
    std::fprintf(stderr, "make_unicode_table: Unicode %s (the system knows %d.%d), %zu classes, %zu combining, %zu pairs\n",
        version, unicode[0], unicode[1], classes.size(), combinings.size(), pairs.size());
    return 0;
}
